    private void coldActorWorkflow(boolean failForce,boolean pending,boolean changedPending,boolean symlink,boolean joint,boolean removed)throws Exception{
        var shape=RatisTopologySeedRuntimeTest.schema();var schema=new DistributedSchema(shape.clusterId(),shape.databaseId(),shape.domainId(),shape.schemaEpoch(),0,shape.columns());
        try(var env=new RatisNodeRuntimeTest.Env(root,false,schema.digest())){
            var source=env.plan.directory();var range=source.ranges().getFirst();var listener=new ReplicaDescriptor(new UUID(122,1),new UUID(122,2),new UUID(122,3),"cold-listener","127.0.0.1:9523",ReplicaDescriptor.Role.LISTENER);var owners=new ArrayList<>(range.replicas());if(removed)owners.removeIf(r->r.nodeId().equals(env.plan.nodeId()) && r.nodeIncarnation().equals(env.plan.nodeIncarnation()));else owners.add(listener);var replacement=new RangeDescriptor(range.rangeId(),range.groupId(),range.rangeEpoch(),range.configurationVersion()+1,range.lowerInclusive(),range.upperExclusive(),range.topologyState(),owners);var ranges=new ArrayList<>(source.ranges());ranges.set(0,replacement);var target=new RangeDirectory(source.clusterId(),source.databaseId(),source.domainId(),source.schemaEpoch(),source.schemaDigest(),source.generation()+1,source.columns(),source.routingPrefixBytes(),ranges);var definition=new TopologyChange.Definition(new UUID(122,4),source,target);var state=TopologyChange.State.begin(definition.header()).beginJoining();
            var authority=(RatisRangeStateMachine.RelocationAuthorityReader)request->{var view=new RatisTopologyJoinAuthority.View(env.plan.catalogue().groupId(),new ApplyPosition(1,8),definition,state);view.require(request);return view;};byte[] originalAuthorization=null;ApplyPosition committed=null;
            for(int attempt=0;attempt<2;attempt++){
                var fake=new RatisNodeRuntimeTest.FakeServer();
                if(attempt==1 && (changedPending || symlink)){assertThrows(java.io.IOException.class,()->RatisNodeRuntime.open(env.plan,env.nodeRoot,ConfigParser.parseDefault(),env.catalogue.epochs,env.routed,env.scheduler,env.timer,()->20L,env.settings(),RatisNodeRuntime.Startup.RECOVER,(plan,logs,machines)->{try{return controlled(fake,plan,logs,machines,new java.util.concurrent.atomic.AtomicBoolean());}catch(Exception failure){throw new java.io.IOException(failure);}},schema));return;}
                try(var node=RatisNodeRuntime.open(env.plan,env.nodeRoot,ConfigParser.parseDefault(),env.catalogue.epochs,env.routed,env.scheduler,env.timer,()->20L,env.settings(),attempt==0?RatisNodeRuntime.Startup.AUTHORIZED_INITIAL_PLACEMENT:RatisNodeRuntime.Startup.RECOVER,(plan,logs,machines)->{try{return controlled(fake,plan,logs,machines,new java.util.concurrent.atomic.AtomicBoolean());}catch(Exception failure){throw new java.io.IOException(failure);}},schema)){
                    for(var entry:fake.machines.entrySet())if(!entry.getKey().getUuid().equals(env.plan.catalogue().groupId()))RatisTopologySeedRuntimeTest.field(entry.getValue(),"relocationAuthority",authority);
                    node.start();var machine=fake.machines.get(RaftGroupId.valueOf(range.groupId()));var store=RatisTopologySeedRuntimeTest.field(machine,"store",ReplicatedRangeStore.class);
                    if(attempt==0){var sourceCfg=store.configuration().data();var targetCfg=RatisRelocationDataClient.targetConfiguration(replacement,sourceCfg);var record=new RatisTopologyRelocationRecord(RatisTopologyRelocationRecord.Action.AUTHORIZE,definition,env.plan.catalogue().groupId(),new ApplyPosition(1,8),sourceCfg,targetCfg);originalAuthorization=record.encode();var forces=new java.util.concurrent.atomic.AtomicInteger();
                        if(failForce){RatisTopologySeedRuntimeTest.field(node,"relocationJournalIo",new RatisNodeRuntime.RelocationJournalIo(){
                            public void write(Path file,byte[] body,int maximum)throws java.io.IOException{var temporary=file.resolveSibling(file.getFileName()+".pending");try(var channel=java.nio.channels.FileChannel.open(temporary,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){byte[] digest=OperatorUpload.sha256(body);var bytes=ByteBuffer.allocate(body.length+digest.length).put(body).put(digest).flip();while(bytes.hasRemaining())channel.write(bytes);channel.force(true);}Files.move(temporary,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);throw new java.io.IOException("Lost original parent force after rename");}
                            public void force(Path file)throws java.io.IOException{RatisNodeRuntime.RELOCATION_FILES.force(file);forces.incrementAndGet();}
                        });var before=store.applied();var persist=RatisNodeRuntime.class.getDeclaredMethod("persistRelocation",RatisTopologyRelocationRecord.class,ApplyPosition.class);persist.setAccessible(true);var runtime=node;var failure=assertThrows(java.lang.reflect.InvocationTargetException.class,()->persist.invoke(runtime,record,new ApplyPosition(1,before.index()+1)));assertInstanceOf(java.io.IOException.class,failure.getCause());assertEquals(before,store.applied());var saved=RatisNodeRuntime.class.getDeclaredMethod("savedRelocation",RatisTopologyRelocationRecord.class);saved.setAccessible(true);assertEquals(false,saved.invoke(node,record));assertEquals(1,forces.get(),"Even a behind-native saved lookup must repair exact file+parent durability");}
                        machine.queryLinearizable(message(RatisRelocationAdmissionRpc.request(RatisRelocationAdmissionRpc.PREPARE,record))).get(5,TimeUnit.SECONDS);
                        var tx=machine.startTransaction(RaftClientRequest.newBuilder().setClientId(ClientId.randomId()).setServerId(RaftPeerId.valueOf(env.plan.peerId())).setGroupId(RaftGroupId.valueOf(range.groupId())).setCallId(122).setType(RaftClientRequest.writeRequestType()).setMessage(message(record.encode())).build());assertNull(tx.getException());machine.preAppendTransaction(tx);tx.initLogEntry(1,store.applied().index()+1);machine.applyTransaction(tx).get(5,TimeUnit.SECONDS);
                        if(failForce){assertTrue(forces.get()>=3,"Fresh admission lookup and existing apply branch must both force exact saved file+parent");}
                        var records=env.nodeRoot.resolve("topology-relocations");try(var files=Files.list(records)){assertEquals(1,files.count(),"Actor intent is forced before configuration can commit");}
                        long index=store.applied().index()+1;byte[] committedCfg=joint?record.jointConfiguration():targetCfg;machine.notifyConfigurationChanged(1,index,org.apache.ratis.proto.RaftProtos.RaftConfigurationProto.parseFrom(committedCfg));machine.notifyTermIndexUpdated(1,index);committed=store.applied();assertArrayEquals(committedCfg,store.configuration().data());
                    }else{assertEquals(committed,store.applied());if(!removed)assertTrue(node.localGroups().stream().filter(g->g.getGroupId().getUuid().equals(range.groupId())).findFirst().orElseThrow().getPeers().stream().anyMatch(peer->peer.getId().toString().equals(listener.peerId())));var groups=RatisTopologySeedRuntimeTest.field(node,"groups",RatisRuntimeGroups.class);assertArrayEquals(originalAuthorization,groups.require(range.groupId()).relocation().encode());assertEquals(RatisTopologyRelocationRecord.Action.AUTHORIZE,groups.require(range.groupId()).relocation().action());assertArrayEquals(source.payloadDigest(),groups.require(range.groupId()).directory().payloadDigest(),"Config reconciliation does not manufacture catalogue publication");assertTrue(store.admissionOpen());
                        if(joint){var record=RatisTopologyRelocationRecord.decode(originalAuthorization);assertTrue(record.requireNativeConfiguration(store.configuration().data()));assertNotNull(env.catalogue.epochs.read(),"Actual borrowed catalogue metadata remains readable during joint DATA recovery");assertThrows(java.util.concurrent.ExecutionException.class,()->machine.queryLinearizable(message(RatisRelocationOwnerRpc.request(new RatisRelocationOwnerRpc.Request(definition,null,RatisRelocationOwnerRpc.Expected.TARGET,null,null)))).get(5,TimeUnit.SECONDS));long next=store.applied().index()+1;machine.notifyConfigurationChanged(1,next,org.apache.ratis.proto.RaftProtos.RaftConfigurationProto.parseFrom(record.targetConfiguration()));machine.notifyTermIndexUpdated(1,next);assertFalse(record.requireNativeConfiguration(store.configuration().data()));fake.actualGroups.put(RaftGroupId.valueOf(range.groupId()),groups.group(record.definition().targets().getFirst()));var targetProof=machine.queryLinearizable(message(RatisRelocationOwnerRpc.request(new RatisRelocationOwnerRpc.Request(definition,null,RatisRelocationOwnerRpc.Expected.TARGET,null,null)))).get(5,TimeUnit.SECONDS);assertTrue(RatisRelocationOwnerRpc.decodeReply(targetProof.getContent().toByteArray(),new RatisRelocationOwnerRpc.Request(definition,null,RatisRelocationOwnerRpc.Expected.TARGET,null,null)).caughtUp());assertArrayEquals(source.payloadDigest(),groups.require(range.groupId()).directory().payloadDigest());}
                        if(removed){var column=schema.columnIds().iterator().next();assertThrows(java.util.concurrent.ExecutionException.class,()->machine.query(message(ScopedTransactionRpc.pointRequest(column,new byte[]{2}))).get(5,TimeUnit.SECONDS));var command=new DistributedCommand(range.groupId(),range.rangeEpoch(),schema.digest(),new OperationId(new UUID(122,8),1,0),List.of(new Mutation(Mutation.Kind.PUT,column,new byte[]{2},new byte[]{3})));var tx=machine.startTransaction(RaftClientRequest.newBuilder().setClientId(ClientId.randomId()).setServerId(RaftPeerId.valueOf(env.plan.peerId())).setGroupId(RaftGroupId.valueOf(range.groupId())).setCallId(124).setType(RaftClientRequest.writeRequestType()).setMessage(message(DistributedCommandCodec.encode(command))).build());assertNotNull(tx.getException());int pins=store.activeSnapshotPins();var statusReply=machine.query(message(ScopedTransactionRpc.frame(ScopedTransactionRpc.STATE,new byte[0]))).get(5,TimeUnit.SECONDS);var statusPacket=ScopedTransactionRpc.parse(statusReply.getContent().toByteArray(),ScopedTransactionRpc.MAX_REPLY_BYTES);var stateView=RangeStateView.decode(statusPacket.body());assertEquals(store.applied(),stateView.applied());assertEquals(range.groupId(),stateView.groupId());assertEquals(pins,store.activeSnapshotPins(),"Removed member metadata status must not allocate USER/native snapshot pins");assertNotNull(env.catalogue.epochs.read(),"Actual borrowed catalogue remains readable");}
                    }
                }
                if(attempt==0 && (pending || changedPending || symlink)){var original=env.nodeRoot.resolve("topology-relocations").resolve(definition.intentId()+".AUTHORIZE");var sidecar=original.resolveSibling(original.getFileName()+".pending");if(pending){Files.move(original,sidecar,StandardCopyOption.ATOMIC_MOVE);SessionJournalFiles.force(sidecar.getParent());}else if(symlink){Files.createSymbolicLink(sidecar,original.getFileName());}else{var body=SessionJournalFiles.read(original,RatisTopologyRelocationRecord.MAX_BYTES+16);var changed=body.clone();ByteBuffer.wrap(changed).putLong(8,ByteBuffer.wrap(body).getLong(8)+1);SessionJournalFiles.write(sidecar,changed,RatisTopologyRelocationRecord.MAX_BYTES+16);}}
            }
        }
    }

    @Test void historicalCompletionKeepsOriginalReplyWithoutRewindingNewerRouteAuthority()throws Exception{
        var shape=RatisTopologySeedRuntimeTest.schema();var schema=new DistributedSchema(shape.clusterId(),shape.databaseId(),shape.domainId(),shape.schemaEpoch(),0,shape.columns());try(var env=new RatisNodeRuntimeTest.Env(root,false,schema.digest())){
            var fake=new RatisNodeRuntimeTest.FakeServer();try(var node=RatisNodeRuntime.open(env.plan,env.nodeRoot,ConfigParser.parseDefault(),env.catalogue.epochs,env.routed,env.scheduler,env.timer,()->20L,env.settings(),RatisNodeRuntime.Startup.AUTHORIZED_INITIAL_PLACEMENT,(plan,logs,machines)->{try{return controlled(fake,plan,logs,machines,new java.util.concurrent.atomic.AtomicBoolean());}catch(Exception failure){throw new java.io.IOException(failure);}},schema)){
                node.start();var initial=env.plan.directory();var range=initial.ranges().getFirst();var machine=fake.machines.get(RaftGroupId.valueOf(range.groupId()));var store=RatisTopologySeedRuntimeTest.field(machine,"store",ReplicatedRangeStore.class);var views=new HashMap<UUID,RatisTopologyJoinAuthority.View>();RatisTopologySeedRuntimeTest.field(machine,"relocationAuthority",(RatisRangeStateMachine.RelocationAuthorityReader)request->{var view=views.get(request.intent());if(view==null)throw new java.io.IOException("Old authority is no longer fresh");view.require(request);return view;});var directory=initial;RatisTopologyRelocationRecord first=null;byte[] originalReply=null;
                for(int n=0;n<2;n++){var old=directory.ranges().getFirst();var owners=new ArrayList<>(old.replicas());owners.add(new ReplicaDescriptor(new UUID(123,10+n),new UUID(123,20+n),new UUID(123,30+n),"historical-listener-"+n,"127.0.0.1:"+(9530+n),ReplicaDescriptor.Role.LISTENER));var changed=new RangeDescriptor(old.rangeId(),old.groupId(),old.rangeEpoch(),old.configurationVersion()+1,old.lowerInclusive(),old.upperExclusive(),old.topologyState(),owners);var ranges=new ArrayList<>(directory.ranges());ranges.set(0,changed);var next=new RangeDirectory(directory.clusterId(),directory.databaseId(),directory.domainId(),directory.schemaEpoch(),directory.schemaDigest(),directory.generation()+1,directory.columns(),directory.routingPrefixBytes(),ranges);var definition=new TopologyChange.Definition(new UUID(123,40+n),directory,next);byte[] sourceCfg=store.configuration().data();byte[] targetCfg=RatisRelocationDataClient.targetConfiguration(changed,sourceCfg);long index=store.applied().index()+1;machine.notifyConfigurationChanged(1,index,org.apache.ratis.proto.RaftProtos.RaftConfigurationProto.parseFrom(targetCfg));machine.notifyTermIndexUpdated(1,index);fake.actualGroups.put(RaftGroupId.valueOf(range.groupId()),RatisTopologySeedRuntimeTest.field(node,"groups",RatisRuntimeGroups.class).group(changed));var local=changed.replicas().stream().filter(r->r.nodeId().equals(env.plan.nodeId())).findFirst().orElseThrow();var proof=new TopologyChange.RelocationProof(range.groupId(),TopologyChange.Owner.of(local),new ApplyPosition(1,index),store.applied(),store.applied(),OperatorUpload.sha256(targetCfg));var state=TopologyChange.State.begin(definition.header()).beginJoining().reconfigured(proof).publishRelocation();views.clear();views.put(definition.intentId(),new RatisTopologyJoinAuthority.View(env.plan.catalogue().groupId(),new ApplyPosition(1,8+n),definition,state));var completion=new RatisTopologyRelocationRecord(RatisTopologyRelocationRecord.Action.COMPLETE,definition,env.plan.catalogue().groupId(),new ApplyPosition(1,8+n),sourceCfg,targetCfg);byte[] reply=appendCompletion(machine,store,completion,env.plan.peerId());if(n==0){first=completion;originalReply=reply;}directory=next;}
                var newer=directory;var afterB=store.applied();var retry=appendCompletion(machine,store,first,env.plan.peerId());assertArrayEquals(originalReply,retry);assertTrue(store.applied().index()>afterB.index());assertArrayEquals(newer.payloadDigest(),RatisTopologySeedRuntimeTest.field(machine,"effectiveSessionDirectory",RangeDirectory.class).payloadDigest());assertEquals(newer.ranges().getFirst(),RatisTopologySeedRuntimeTest.field(machine,"topologyDescriptor",RangeDescriptor.class));assertEquals(newer.ranges().getFirst(),RatisTopologySeedRuntimeTest.field(machine,"schemaDescriptor",RangeDescriptor.class));assertArrayEquals(newer.payloadDigest(),RatisTopologySeedRuntimeTest.field(node,"groups",RatisRuntimeGroups.class).require(range.groupId()).directory().payloadDigest());assertArrayEquals(newer.payloadDigest(),env.routed.directory().payloadDigest());
            }
        }
    }
    static byte[] appendCompletion(RatisRangeStateMachine machine,ReplicatedRangeStore store,RatisTopologyRelocationRecord record,String peer)throws Exception{
        machine.queryLinearizable(message(RatisRelocationAdmissionRpc.request(RatisRelocationAdmissionRpc.PREPARE,record))).get(5,TimeUnit.SECONDS);var tx=machine.startTransaction(RaftClientRequest.newBuilder().setClientId(ClientId.randomId()).setServerId(RaftPeerId.valueOf(peer)).setGroupId(machine.getGroupId()).setCallId(123).setType(RaftClientRequest.writeRequestType()).setMessage(message(record.encode())).build());assertNull(tx.getException());machine.preAppendTransaction(tx);tx.initLogEntry(1,store.applied().index()+1);return machine.applyTransaction(tx).get(5,TimeUnit.SECONDS).getContent().toByteArray();
    }

